
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th_fcfo_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th_fcfo", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.943322464071568e+00, -4.848187873604375e+00, -4.713471346234430e+00, -4.524408021247410e+00, -4.262955762240540e+00, -3.910123402319254e+00, -3.452924402001567e+00, -2.899184035729580e+00, -2.299480764173520e+00, -1.749983669253916e+00, -1.264479993630016e+00, -9.170091339887448e-01, -8.357604151522768e-01, -7.258087546480939e-01, -5.927231881983611e-01, -4.675979197662198e-01, -3.674596083219624e-01, -2.955575356710416e-01, -2.518889529591302e-01, -2.141710170324376e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


